fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    // Create a vector of tuples (value, index) for the three indices
    let mut indices = vec![
        (valores[i], i),
        (valores[j], j),
        (valores[k], k),
    ];
    
    // Sort in descending order by value
    // For equal values, we don't care about the order, so we can use sort_by with reverse
    indices.sort_by(|a, b| b.0.cmp(&a.0));
    
    // Return the first two indices
    (indices[0].1, indices[1].1)
}